package status

// Shared item schemas for the admin path fragment in admin.go. Each constant
// mirrors the Go mapper that emits the payload; keep them in lockstep with
// the handlers in go/internal/query/admin. The fragments splice these
// constants into their raw JSON with string concatenation so the work-item
// family is defined once instead of drifting across four copies.
const (
	// adminWorkItemSchema is one fact_work_items row as projected by
	// admin.workItemsToSlice: nine fixed keys plus the lease, failure,
	// note, prior-failure, and visibility keys the mapper adds
	// conditionally.
	adminWorkItemSchema = `{"type": "object", "description": "One fact work-item row. Owner: admin.workItemsToSlice via admin.WorkItem.", "required": ["work_item_id", "scope_id", "generation_id", "stage", "domain", "status", "attempt_count", "created_at", "updated_at"], "properties": {"work_item_id": {"type": "string", "description": "Work-item id. Owner: admin.workItemsToSlice via WorkItemID."}, "scope_id": {"type": "string", "description": "Ingestion scope id. Owner: admin.workItemsToSlice via ScopeID."}, "generation_id": {"type": "string", "description": "Generation id. Owner: admin.workItemsToSlice via GenerationID."}, "stage": {"type": "string", "description": "Pipeline stage. Owner: admin.workItemsToSlice via Stage."}, "domain": {"type": "string", "description": "Reducer or projection domain. Owner: admin.workItemsToSlice via Domain."}, "status": {"type": "string", "description": "Work-item status. Owner: admin.workItemsToSlice via Status."}, "attempt_count": {"type": "integer", "description": "Claim attempts spent. Owner: admin.workItemsToSlice via AttemptCount."}, "created_at": {"type": "string", "format": "date-time", "description": "Row creation time. Owner: admin.workItemsToSlice via CreatedAt."}, "updated_at": {"type": "string", "format": "date-time", "description": "Last update time. Owner: admin.workItemsToSlice via UpdatedAt."}, "lease_owner": {"type": "string", "description": "Current lease holder; present only on claimed rows. Owner: admin.workItemsToSlice via LeaseOwner."}, "failure_class": {"type": "string", "description": "Machine failure class; present only on failed rows. Owner: admin.workItemsToSlice via FailureClass."}, "failure_message": {"type": "string", "description": "Failure detail; present only on failed rows. Owner: admin.workItemsToSlice via FailureMessage."}, "operator_note": {"type": "string", "description": "Operator note; present only when set. Owner: admin.workItemsToSlice via OperatorNote."}, "prior_failure": {"type": "object", "description": "Failure evidence kept across an overwrite; present only when the row carries failure_details. Owner: admin.workItemsToSlice via PriorFailure.", "properties": {"status": {"type": "string", "description": "Prior status. Owner: admin.PriorFailure Status."}, "failure_class": {"type": "string", "description": "Prior failure class. Owner: admin.PriorFailure FailureClass."}, "failure_message": {"type": "string", "description": "Prior failure message. Owner: admin.PriorFailure FailureMessage."}, "updated_at": {"type": "string", "description": "Prior update time. Owner: admin.PriorFailure UpdatedAt."}}}, "visible_at": {"type": "string", "format": "date-time", "description": "Visibility time; present only when set. Owner: admin.workItemsToSlice via VisibleAt."}}}`

	// adminDecisionEvidenceSchema is one projection-decision evidence row
	// as projected by admin.evidenceRowsToSlice: five fixed keys plus
	// fact_id.
	adminDecisionEvidenceSchema = `{"type": "object", "description": "One projection-decision evidence row. Owner: admin.evidenceRowsToSlice via admin.EvidenceRow.", "required": ["evidence_id", "decision_id", "evidence_kind", "detail", "created_at"], "properties": {"evidence_id": {"type": "string", "description": "Evidence id. Owner: admin.evidenceRowsToSlice via EvidenceID."}, "decision_id": {"type": "string", "description": "Owning decision id. Owner: admin.evidenceRowsToSlice via DecisionID."}, "evidence_kind": {"type": "string", "description": "Evidence kind. Owner: admin.evidenceRowsToSlice via EvidenceKind."}, "detail": {"type": "object", "additionalProperties": true, "description": "Evidence detail attributes keyed by attribute name; the key set varies by evidence kind. Owner: admin.evidenceRowsToSlice via Detail."}, "created_at": {"type": "string", "format": "date-time", "description": "Row creation time. Owner: admin.evidenceRowsToSlice via CreatedAt."}, "fact_id": {"type": "string", "description": "Source fact id; present only when the evidence cites a fact. Owner: admin.evidenceRowsToSlice via FactID."}}}`

	// adminDecisionSchema is one projection decision as projected by
	// admin.decisionRowToMap: ten fixed keys plus the evidence member the
	// handler adds only with include_evidence.
	adminDecisionSchema = `{"type": "object", "description": "One projection decision. Owner: admin.decisionRowToMap via admin.DecisionRow.", "required": ["decision_id", "decision_type", "repository_id", "source_run_id", "work_item_id", "subject", "confidence_score", "confidence_reason", "provenance_summary", "created_at"], "properties": {"decision_id": {"type": "string", "description": "Decision id. Owner: admin.decisionRowToMap via DecisionID."}, "decision_type": {"type": "string", "description": "Decision type. Owner: admin.decisionRowToMap via DecisionType."}, "repository_id": {"type": "string", "description": "Repository id. Owner: admin.decisionRowToMap via RepositoryID."}, "source_run_id": {"type": "string", "description": "Source run id. Owner: admin.decisionRowToMap via SourceRunID."}, "work_item_id": {"type": "string", "description": "Work-item id. Owner: admin.decisionRowToMap via WorkItemID."}, "subject": {"type": "string", "description": "Decision subject. Owner: admin.decisionRowToMap via Subject."}, "confidence_score": {"type": "number", "description": "Decision confidence score. Owner: admin.decisionRowToMap via ConfidenceScore."}, "confidence_reason": {"type": "string", "description": "Confidence reason. Owner: admin.decisionRowToMap via ConfidenceReason."}, "provenance_summary": {"type": "object", "additionalProperties": true, "description": "Provenance attributes keyed by attribute name; the key set varies by decision type. Owner: admin.decisionRowToMap via ProvenanceSummary."}, "created_at": {"type": "string", "format": "date-time", "description": "Row creation time. Owner: admin.decisionRowToMap via CreatedAt."}, "evidence": {"type": "array", "description": "Evidence rows; present only with include_evidence. Owner: admin.listDecisions.", "items": ` + adminDecisionEvidenceSchema + `}}}`

	// adminDeadLetterItemSchema is one durable dead-letter row as projected
	// by admin.deadLetterItemsToSlice: nine fixed keys plus failure_class
	// and visible_at.
	adminDeadLetterItemSchema = `{"type": "object", "description": "One durable dead-letter row. Owner: admin.deadLetterItemsToSlice via admin.DeadLetterWorkItem.", "required": ["work_item_id", "scope_id", "generation_id", "stage", "domain", "collector_kind", "attempt_count", "created_at", "updated_at"], "properties": {"work_item_id": {"type": "string", "description": "Work-item id. Owner: admin.deadLetterItemsToSlice via WorkItemID."}, "scope_id": {"type": "string", "description": "Ingestion scope id. Owner: admin.deadLetterItemsToSlice via ScopeID."}, "generation_id": {"type": "string", "description": "Generation id. Owner: admin.deadLetterItemsToSlice via GenerationID."}, "stage": {"type": "string", "description": "Pipeline stage. Owner: admin.deadLetterItemsToSlice via Stage."}, "domain": {"type": "string", "description": "Reducer or projection domain. Owner: admin.deadLetterItemsToSlice via Domain."}, "collector_kind": {"type": "string", "description": "Collector kind. Owner: admin.deadLetterItemsToSlice via CollectorKind."}, "attempt_count": {"type": "integer", "description": "Claim attempts spent. Owner: admin.deadLetterItemsToSlice via AttemptCount."}, "created_at": {"type": "string", "format": "date-time", "description": "Row creation time. Owner: admin.deadLetterItemsToSlice via CreatedAt."}, "updated_at": {"type": "string", "format": "date-time", "description": "Last update time. Owner: admin.deadLetterItemsToSlice via UpdatedAt."}, "failure_class": {"type": "string", "description": "Machine failure class; present only on failed rows. Owner: admin.deadLetterItemsToSlice via FailureClass."}, "visible_at": {"type": "string", "format": "date-time", "description": "Visibility time; present only when set. Owner: admin.deadLetterItemsToSlice via VisibleAt."}}}`

	// adminInputInvalidFactSchema is one quarantined input_invalid fact.
	// Owner: admin.InputInvalidFact, marshaled directly with no omitempty,
	// so every key is fixed.
	adminInputInvalidFactSchema = `{"type": "object", "description": "One quarantined reducer_input_invalid_facts row. Owner: admin.InputInvalidFact.", "required": ["fact_id", "fact_kind", "missing_field", "failure_class", "domain", "scope_id", "generation_id", "decided_at"], "properties": {"fact_id": {"type": "string", "description": "Quarantined fact id. Owner: admin.InputInvalidFact FactID."}, "fact_kind": {"type": "string", "description": "Fact kind. Owner: admin.InputInvalidFact FactKind."}, "missing_field": {"type": "string", "description": "Required field that was missing or null. Owner: admin.InputInvalidFact MissingField."}, "failure_class": {"type": "string", "description": "Machine failure class. Owner: admin.InputInvalidFact FailureClass."}, "domain": {"type": "string", "description": "Reducer domain. Owner: admin.InputInvalidFact Domain."}, "scope_id": {"type": "string", "description": "Ingestion scope id. Owner: admin.InputInvalidFact ScopeID."}, "generation_id": {"type": "string", "description": "Generation id. Owner: admin.InputInvalidFact GenerationID."}, "decided_at": {"type": "string", "format": "date-time", "description": "Quarantine time. Owner: admin.InputInvalidFact DecidedAt."}}}`

	// adminPoisonedLinkSchema is one changed_since_scope_cursor row as served
	// by admin.listChangedSincePoisonedLinks: five fixed keys plus the
	// conditional time and class keys.
	adminPoisonedLinkSchema = `{"type": "object", "description": "One poisoned or retrying changed-since link. Owner: admin.ChangedSincePoisonedLink.", "required": ["scope_id", "status", "activation_seq", "attempt_count", "updated_at"], "properties": {"scope_id": {"type": "string", "description": "Scope id. Owner: admin.ChangedSincePoisonedLink ScopeID."}, "status": {"type": "string", "enum": ["poisoned", "retrying"], "description": "Link status. Owner: admin.ChangedSincePoisonedLink Status."}, "activation_seq": {"type": "integer", "description": "Head activation the scope is stuck on. Owner: admin.ChangedSincePoisonedLink ActivationSeq."}, "attempt_count": {"type": "integer", "description": "Counting failures observed. Owner: admin.ChangedSincePoisonedLink AttemptCount."}, "updated_at": {"type": "string", "format": "date-time", "description": "Last update time. Owner: admin.ChangedSincePoisonedLink UpdatedAt."}, "last_failure_class": {"type": "string", "description": "Last failure class; present only when set. Owner: admin.ChangedSincePoisonedLink LastFailureClass."}, "next_attempt_at": {"type": "string", "format": "date-time", "description": "Next attempt time; present only while backing off. Owner: admin.ChangedSincePoisonedLink NextAttemptAt."}, "poisoned_at": {"type": "string", "format": "date-time", "description": "Poisoning time; present only on poisoned links. Owner: admin.ChangedSincePoisonedLink PoisonedAt."}}}`

	// adminReplayEventSchema is one replay-event row as projected by
	// admin.listReplayEvents: five fixed keys plus failure_class and
	// operator_note.
	adminReplayEventSchema = `{"type": "object", "description": "One replay-event audit row. Owner: admin.listReplayEvents via admin.ReplayEvent.", "required": ["replay_event_id", "work_item_id", "scope_id", "generation_id", "created_at"], "properties": {"replay_event_id": {"type": "string", "description": "Replay-event id. Owner: admin.listReplayEvents via ReplayEventID."}, "work_item_id": {"type": "string", "description": "Replayed work-item id. Owner: admin.listReplayEvents via WorkItemID."}, "scope_id": {"type": "string", "description": "Ingestion scope id. Owner: admin.listReplayEvents via ScopeID."}, "generation_id": {"type": "string", "description": "Generation id. Owner: admin.listReplayEvents via GenerationID."}, "created_at": {"type": "string", "format": "date-time", "description": "Row creation time. Owner: admin.listReplayEvents via CreatedAt."}, "failure_class": {"type": "string", "description": "Machine failure class; present only when set. Owner: admin.listReplayEvents via FailureClass."}, "operator_note": {"type": "string", "description": "Operator note; present only when set. Owner: admin.listReplayEvents via OperatorNote."}}}`

	// adminBackfillRequestSchema is one backfill request row as projected by
	// admin.backfill: two fixed keys plus the request selectors.
	adminBackfillRequestSchema = `{"type": "object", "description": "One backfill request row. Owner: admin.backfill via admin.BackfillRequest.", "required": ["backfill_request_id", "created_at"], "properties": {"backfill_request_id": {"type": "string", "description": "Backfill request id. Owner: admin.backfill via BackfillRequestID."}, "created_at": {"type": "string", "format": "date-time", "description": "Row creation time. Owner: admin.backfill via CreatedAt."}, "scope_id": {"type": "string", "description": "Scope selector; present only when the request named one. Owner: admin.backfill via ScopeID."}, "generation_id": {"type": "string", "description": "Generation selector; present only when the request named one. Owner: admin.backfill via GenerationID."}, "operator_note": {"type": "string", "description": "Operator note; present only when set. Owner: admin.backfill via OperatorNote."}}}`

	// adminReopenedUnitSchema is one reopened shared-projection acceptance
	// unit as projected by admin.reopenedUnitsToSlice.
	adminReopenedUnitSchema = `{"type": "object", "description": "One reopened shared-projection acceptance unit. Owner: admin.reopenedUnitsToSlice via admin.ReopenedUnit.", "required": ["acceptance_unit_id", "source_run_id", "intent_id"], "properties": {"acceptance_unit_id": {"type": "string", "description": "Acceptance unit id. Owner: admin.reopenedUnitsToSlice via AcceptanceUnitID."}, "source_run_id": {"type": "string", "description": "Source run id. Owner: admin.reopenedUnitsToSlice via SourceRunID."}, "intent_id": {"type": "string", "description": "Shared-projection intent id. Owner: admin.reopenedUnitsToSlice via IntentID."}}}`
)
